/**
 * The TradingView indicator that mirrors this engine, plus its manual.
 *
 * The Pine source is served verbatim from `public/` so the download button
 * hands over exactly the text that gets pasted into the Pine Editor. The manual
 * is generated by `bun run scripts/build-indicator-manual.ts`.
 */
export const PINE_URL = "/nova-exhaustion-trap.pine";
export const PINE_FILENAME = "nova-exhaustion-trap.pine";
/**
 * v1.1 narrowed the model to bull traps at the 24h high — shorts only.
 * v1.2 made gate 4 a two-sided band and built the horizon high from completed
 * daily bars only, so a fresh breakout can no longer define its own extreme.
 */
export const PINE_VERSION = "v1.2";

export const INDICATOR_MANUAL_URL = "/nova-exhaustion-manual.pdf";
export const INDICATOR_MANUAL_VERSION = "v1.2";
/** Kept in step with the build script's reported output. */
export const INDICATOR_MANUAL_PAGES = 12;
export const INDICATOR_MANUAL_FIGURES = 7;

/**
 * Companion indicator: VWAP extension filter.
 *
 * Independent of the exhaustion engine — it answers a different question
 * ("is price stretched far enough from value to be worth trading?") and is
 * shipped as a standalone Pine file.
 */
export const VWAP_PINE_URL = "/nova-vwap-distance-pro.pine";
export const VWAP_PINE_FILENAME = "nova-vwap-distance-pro.pine";
export const VWAP_PINE_VERSION = "v2.0";

/**
 * Companion indicator: traps at monthly levels on the daily chart.
 *
 * Same four-gate discipline as the exhaustion engine, applied to daily candles
 * at the previous month's high/low and monthly supply/demand zones, in both
 * directions. Standalone Pine file; the defaults are the backtested rules.
 *
 * v1.1 added a market-regime door (Bitcoin below its rising 200-day average for
 * longs, below the average for shorts), an intrabar wick proof (volume beyond
 * the level and participation after the extreme), quarter/year levels drawn
 * and tagged as confluence, and the dashboard universe note. Measured on the
 * same 50-pair 2017–2026 history as v1.0.
 * v1.2 added the intraday volume profile read from the same intrabars: POC and
 * high-volume clusters drawn beside the last candle, a confluence tier per
 * signal (POC inside the rejection wick, ★ when also beyond the level), and a
 * caution flag when the wick lands inside the previous session's value.
 */
export const MONTHLY_PINE_URL = "/nova-monthly-trap.pine";
export const MONTHLY_PINE_FILENAME = "nova-monthly-trap.pine";
export const MONTHLY_PINE_VERSION = "v1.2";

